edit('src/map/cesium-adapter.js','  const graphEntities = [];','  let activeBasemap = null, imagerySerial = 0;\n  let onlineLayers = [];\n  const imageryStatus = document.createElement("div"); imageryStatus.className="imagery-status"; imageryStatus.setAttribute("role","status");container.append(imageryStatus);\n  async function setBasemap(id) {\n    if(id === activeBasemap) return; activeBasemap=id; const serial=++imagerySerial;\n    const config=basemapConfig(id);\n    for(const layer of onlineLayers) viewer.imageryLayers.remove(layer,true);onlineLayers=[];\n    container.dataset.imageryProvider=id;container.dataset.imageryStatus=config?"loading":"coarse-offline";\n    imageryStatus.textContent=config?`${config.name} loading · coarse geography underneath. ${config.coverage}`:"Offline coarse geography · no detailed imagery. Ellipsoid, no elevation terrain.";\n    if(!config) return;\n    try {\n      const provider=await Cesium.ArcGisMapServerImageryProvider.fromUrl(config.service,{enablePickFeatures:false,maximumLevel:config.maximumLevel,credit:new Cesium.Credit(config.credit)});\n      if(serial!==imagerySerial || !alive) return;\n      let failures=0;const original=provider.requestImage.bind(provider);\n      provider.requestImage=(x,y,level,request)=>{\n        const result=original(x,y,level,request);\n        if(result?.then) return result.then(image=>{if(alive&&serial===imagerySerial){container.dataset.imageryLoadedLevel=String(Math.max(level,Number(container.dataset.imageryLoadedLevel)||0));container.dataset.imageryStatus=failures?"partial":"available";}return image;});\n        return result;\n      };\n      provider.errorEvent.addEventListener(()=>{if(serial!==imagerySerial||!alive)return;failures++;container.dataset.imageryStatus="degraded";imageryStatus.textContent=`${config.name} tile failure · coarse fallback or partial tiles. ${config.coverage}`;viewer.scene.requestRender();});\n      const layer=new Cesium.ImageryLayer(provider);onlineLayers.push(layer);viewer.imageryLayers.add(layer);\n      imageryStatus.textContent=`${config.name} · finest service level ${config.maximumLevel}. ${config.coverage} Ellipsoid terrain.`;\n      viewer.scene.requestRender();\n    } catch {if(alive&&serial===imagerySerial){container.dataset.imageryStatus="degraded";imageryStatus.textContent=`${config.name} unavailable · coarse fallback. ${config.coverage}`;}}\n  }\n  const graphEntities = [];')
